"""Generate and execute notebooks/analysis.ipynb (the walkthrough of the analysis).

Usage:
    python scripts/make_notebook.py
"""
from pathlib import Path

import nbformat
from nbclient import NotebookClient

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "notebooks" / "analysis.ipynb"

md = nbformat.v4.new_markdown_cell
code = nbformat.v4.new_code_cell

cells = [
    md("# Support quality analytics\n\n"
       "> **Synthetic data.** Every row was generated by `scripts/generate_data.py`. "
       "It is not real company data.\n\n"
       "A walkthrough of the analysis. The logic lives in the SQL files under `sql/`.\n\n"
       "**Questions a support / QA manager would ask**\n"
       "1. Are we meeting SLA, and when do we miss it?\n"
       "2. Which QA criteria fail most, and who is most at risk of errors?\n"
       "3. Do QA errors actually affect customers (CSAT, reopens)?\n"
       "4. Are our QA evaluators scoring consistently?\n"
       "5. Did the Team C coaching programme work?\n"
       "6. Which agents should get coaching next?"),
    code("import sys\nfrom pathlib import Path\n\n"
         "ROOT = Path.cwd().parent if Path.cwd().name == 'notebooks' else Path.cwd()\n"
         "sys.path.insert(0, str(ROOT / 'src'))\n\n"
         "import pandas as pd\nfrom pipeline import build\n\n"
         "pd.set_option('display.width', 180)\n"
         "con = build()\n"
         "sql = lambda q: con.sql(q).df()"),
    md("## 1. Data quality\nIssues found in the raw extracts, and how `sql/01_clean.sql` handles each one."),
    code("sql('SELECT check_name, rows_affected, action FROM data_quality')"),
    code("sql('SELECT * FROM headline_kpis')"),
    md("## 2. SLA and operations"),
    code("sql('SELECT month, tickets, sla_met_pct, median_resolution_hours, csat_pct FROM monthly_ops')"),
    code("sql('''SELECT weekday, sum(tickets) AS tickets,\n"
         "              round(sum(tickets * sla_met_pct) / sum(tickets), 1) AS sla_met_pct\n"
         "       FROM sla_by_weekday GROUP BY weekday, weekday_num ORDER BY weekday_num''')"),
    code("sql('SELECT * FROM category_ops')"),
    md("SLA falls during the Nov–Dec peak and on Mondays. Both are high-volume periods, so this points to staffing, "
       "not agent quality. Billing disputes and technical issues have the highest escalation rates and the lowest CSAT."),
    md("## 3. Quality: what fails and who fails it"),
    code("sql('SELECT * FROM qa_by_criterion')"),
    code("sql('SELECT * FROM qa_by_tenure')"),
    md("## 4. Do QA errors reach the customer?"),
    code("sql('SELECT * FROM qa_vs_outcomes')"),
    code("sql('SELECT * FROM criterion_impact')"),
    md("Accuracy errors are the most damaging to CSAT and reopens. Verification and greeting errors barely move CSAT, "
       "because customers do not see them. That is exactly why verification needs QA: it is a risk the customer survey will never reveal."),
    md("## 5. Evaluator calibration"),
    code("sql('SELECT * FROM evaluator_calibration ORDER BY criteria_type, agreement_pct')"),
    code("sql('SELECT * FROM evaluator_scoring')"),
    md("QE04 fails soft-skill criteria that the majority passes, and scores agents about 4 points lower in live QA. "
       "QE06 is lenient on the same criteria. Because tickets are assigned to evaluators at random, an agent's score "
       "partly depends on who evaluated them. Recalibrate before using these scores in performance reviews."),
    md("## 6. Coaching impact (difference-in-differences)"),
    code("sql('SELECT * FROM coaching_impact')"),
    code("sql('SELECT * FROM coaching_did')"),
    code("sql('SELECT * FROM coaching_trend')"),
    md("Comparing Team C's change with the change for other teams over the same period removes effects that hit everyone, "
       "such as seasonality. The effect builds over time: Q3 2026 shows the biggest gap."),
    md("## 7. Agent scorecard (Jul–Sep 2026)"),
    code("sql('SELECT * FROM agent_scorecard WHERE flag IS NOT NULL')"),
    md("## 8. Recommendations\n"
       "1. **Staff for Mondays and the Nov–Dec peak.** SLA misses follow volume, not agent quality.\n"
       "2. **Focus QA on accuracy and on agents in their first 3 months.** These are the errors that drive reopens and low CSAT.\n"
       "3. **Recalibrate QE04 and QE06** on soft-skill criteria before their scores feed into agent reviews.\n"
       "4. **Roll out the Team C coaching programme** to other teams, starting with the teams of the flagged agents.\n"
       "5. **Fix data capture.** 1% of tickets have no channel, and some survey and timestamp values are invalid.\n\n"
       "**Limitations:** synthetic data, so the size of each effect comes from the generator's settings. "
       "The value of this project is the method: the queries, checks and comparisons apply unchanged to real ticket and QA data."),
]

nb = nbformat.v4.new_notebook(cells=cells)
nb.metadata["kernelspec"] = {"name": "python3", "display_name": "Python 3", "language": "python"}
OUT.parent.mkdir(exist_ok=True)
NotebookClient(nb, timeout=600, kernel_name="python3", resources={"metadata": {"path": str(OUT.parent)}}).execute()
nbformat.write(nb, OUT)
print(f"Wrote {OUT}")
